-- V15: Furniture Models and Collections for 3D Decor Studio
-- PostgreSQL compatible, with JSONB metadata and GIN indexing

CREATE TABLE model_collections (
    id VARCHAR(36) NOT NULL PRIMARY KEY,
    code VARCHAR(100) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    description TEXT NULL,
    style VARCHAR(30) NOT NULL,               -- 'STYLIZED' | 'REALISTIC'
    default_tier VARCHAR(20) NOT NULL DEFAULT 'FREE', -- 'FREE' | 'PREMIUM'
    thumbnail_url VARCHAR(500) NULL,
    author_or_source VARCHAR(200) NULL,
    license VARCHAR(100) NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', -- 'ACTIVE' | 'INACTIVE' | 'DRAFT'
    sort_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_model_collections_style ON model_collections(style);
CREATE INDEX idx_model_collections_status ON model_collections(status);

CREATE TABLE furniture_models (
    id VARCHAR(36) NOT NULL PRIMARY KEY,
    code VARCHAR(150) NOT NULL UNIQUE,
    name VARCHAR(250) NOT NULL,
    collection_id VARCHAR(36) NOT NULL,
    category VARCHAR(50) NOT NULL,
    model_type VARCHAR(50) NOT NULL,
    mount_type VARCHAR(20) NOT NULL DEFAULT 'floor',
    style VARCHAR(30) NOT NULL,
    tier VARCHAR(20) NOT NULL DEFAULT 'free',
    required_plan VARCHAR(20) NOT NULL DEFAULT 'FREE',
    price BIGINT NOT NULL DEFAULT 0,
    model_path VARCHAR(500) NULL,
    thumbnail_path VARCHAR(500) NULL,
    dimension_x DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    dimension_y DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    dimension_z DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    is_surface_host BOOLEAN NOT NULL DEFAULT FALSE,
    can_place_on_surface BOOLEAN NOT NULL DEFAULT FALSE,
    file_size_bytes BIGINT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    sort_order INTEGER NOT NULL DEFAULT 0,
    tags VARCHAR(500) NULL,
    metadata_json JSONB NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_furniture_models_collection FOREIGN KEY (collection_id) REFERENCES model_collections(id)
);

CREATE INDEX idx_furniture_models_collection ON furniture_models(collection_id);
CREATE INDEX idx_furniture_models_category ON furniture_models(category);
CREATE INDEX idx_furniture_models_type ON furniture_models(model_type);
CREATE INDEX idx_furniture_models_style_tier ON furniture_models(style, tier);
CREATE INDEX idx_furniture_models_status ON furniture_models(status);
CREATE INDEX idx_furniture_models_metadata ON furniture_models USING gin (metadata_json);

